def runningMode(nums):
    count = {}
    best = 0
    mode = None
    out = []
    for x in nums:
        c = count.get(x, 0) + 1
        count[x] = c
        if c > best:
            best = c
            mode = x
        elif c == best and x < mode:
            mode = x
        out.append(mode)
    return out
